 function collectChanges(){const changes=new Map();document.querySelectorAll('#oa-costs input[data-cost-key]').forEach(input=>{const key=`${input.dataset.costKind}:${input.dataset.costKey}`;if(!changes.has(key))changes.set(key,{kind:input.dataset.costKind,key:input.dataset.costKey,values:{}});if(input.dataset.field==='electricityIncluded'){if(String(input.checked)!==input.dataset.original)changes.get(key).values.electricityIncluded=input.checked?1:0;return;}const clear=document.querySelector(`[data-clear-key="${CSS.escape(input.dataset.costKey)}"][data-clear-kind="${CSS.escape(input.dataset.costKind)}"][data-field="${CSS.escape(input.dataset.field)}"]`);if(clear?.checked){changes.get(key).values[input.dataset.field]=null;return;}if(input.value===''||input.value===input.dataset.original)return;const value=costInteger(input.dataset.field,input.value);if(value!==undefined)changes.get(key).values[input.dataset.field]=value;});return [...changes.values()].filter(x=>Object.keys(x.values).length);}
 async function saveCosts(){if(state.scope!=='financial'||!state.canEdit){setMessage($('oa-cost-message'),'Редактирование недоступно.','error');return;}if(!state.pendingCostPayload){const changes=collectChanges();if(!changes.length){setMessage($('oa-cost-message'),'Нет изменений для сохранения.');return;}state.pendingCostPayload={requestId:crypto.randomUUID(),revision:state.costs.revision,changes};}const button=$('oa-cost-save');button.disabled=true;lockCostForm(true);setMessage($('oa-cost-message'),'Сохранение ставок…');try{const saved=await request('/api/admin/financial-analytics/costs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(state.pendingCostPayload)});state.pendingCostPayload=null;state.costs=saved;state.role=saved.role||state.role;state.canEdit=saved.canEdit===true;renderCosts();lockCostForm(false);button.textContent='Сохранить ставки';recalcScenario();setMessage($('oa-cost-message'),'Ставки сохранены.');}catch(e){button.disabled=false;if(e.status===409){state.pendingCostPayload=null;lockCostForm(false);button.textContent='Сохранить ставки';await loadCosts({preserveDraft:true,notice:'Версия изменилась. Значения сервера показаны в подсказках; черновик сохранён.'});return;}if(e.status===401||e.status===403||e.status>=400&&e.status<500){state.pendingCostPayload=null;lockCostForm(false);button.textContent='Сохранить ставки';showAuthError($('oa-cost-message'),e);return;}lockCostForm(true);$('oa-cost-reload').disabled=true;button.textContent='Повторить сохранение';button.title='Повторить тот же запрос с тем же идентификатором';setMessage($('oa-cost-message'),'Результат запроса не подтверждён. Повторите тот же запрос; поля заблокированы до подтверждения.','error');}}
 function knownRentalCost(key){const row=(state.costs?.rows||[]).find(x=>x.kind==='rental'&&String(x.key)===String(key));if(!row)return null;const f=row.fields||{};if(n(f.issueCents)===null||n(f.hourCents)===null)return null;let hourly=Number(f.hourCents)/100;if(['catamaran','electric'].includes(String(key))&&Number(f.electricityIncluded)!==1){if(n(f.electricityIncluded)===null||n(f.kwhPerHour)===null||n(f.electricityTariffCents)===null)return null;hourly+=Number(f.kwhPerHour)*Number(f.electricityTariffCents)/100;}return {hourly,unit:Number(f.issueCents)/100};}
 function lostCafeContribution(){const period=state.data?.period,start=$('oa-sat-start').value,end=$('oa-sat-end').value;if(!period||!start||!end||start>=end)return null;const from=start.split(':').map(Number),to=end.split(':').map(Number),begin=from[0]*60+from[1],finish=to[0]*60+to[1],buckets=state.data?.cafe?.buckets||[];let total=0,saturdays=0;for(let stamp=Date.parse(period.from+'T12:00:00Z');stamp<=Date.parse(period.to+'T12:00:00Z');stamp+=DAY){if(new Date(stamp).getUTCDay()!==6)continue;saturdays++;const day=new Date(stamp).toISOString().slice(0,10);for(let hour=Math.floor(begin/60);hour<Math.ceil(finish/60);hour++){const overlap=Math.max(0,Math.min(finish,(hour+1)*60)-Math.max(begin,hour*60));if(!overlap)continue;for(const item of buckets.filter(x=>x.day===day&&x.hour===hour)){const value=n(item.contributionCents);if(value===null)return null;total+=value*overlap/60;}}}return saturdays?total/saturdays:null;}
 function recalcScenario(){const out=$('oa-scenario-result'),known=lostCafeContribution(),cost=knownRentalCost($('oa-rental-equipment').value);if(known===null){out.textContent='Нужен известный вклад кафе за субботнее окно; расчёт усредняет календарные субботы периода.';return;}if(!cost){out.textContent='Заполните известную себестоимость выбранной техники: выдачу, час и применимое электричество.';return;}const result=scenario({knownContribution:known/100,hours:$('oa-wage-hours').value,rate:$('oa-wage-rate').value,units:$('oa-extra-units').value,rentalHours:$('oa-rental-hours').value,rentalPrice:$('oa-rental-price').value,rentalHourlyCost:cost.hourly,rentalUnitCost:cost.unit});if(!result){out.textContent='Укажите ставку, сокращаемые часы оплаты, дополнительные выдачи, часы на единицу и цену. Пустые значения не считаются нулём.';return;}out.textContent=`Оценка среднего субботнего окна ${$('oa-sat-start').value}–${$('oa-sat-end').value}: экономия труда ${rub(Math.round(result.labour*100))} + предполагаемый вклад проката ${rub(Math.round(result.rental*100))} − потерянный вклад кафе ${rub(Math.round(known))} = ${signedRub(Math.round(result.net*100))}. Перевод сотрудника без сокращения оплачиваемых часов не создаёт экономию. Спрос и свободная мощность не гарантируются.`;}
