 const scheduleFrame=callback=>typeof requestAnimationFrame==='function'?requestAnimationFrame(callback):setTimeout(callback,0);
 function activateTab(tab){state.activeTab=tab;document.querySelectorAll('.oa-tabs [role=tab]').forEach(b=>{const active=b.dataset.tab===tab;b.setAttribute('aria-selected',String(active));$(b.getAttribute('aria-controls')).hidden=!active;});if(tab==='overview'&&state.scope==='operations')scheduleFrame(()=>renderTrends());if(tab==='costs'&&!state.costs)loadCosts();if(tab==='expenses'&&typeof window.dispatchEvent==='function'&&typeof CustomEvent==='function')window.dispatchEvent(new CustomEvent('operations-analytics-expenses-open',{detail:range()}));}
 document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>activateTab(b.dataset.tab)));
 document.querySelectorAll('[data-trend-mode]').forEach(b=>b.addEventListener('click',()=>{state.trendMode=b.dataset.trendMode;document.querySelectorAll('[data-trend-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderTrends();}));
 document.querySelectorAll('[data-preset]').forEach(b=>b.addEventListener('click',()=>setRange(b.dataset.preset)));
